content.arguments:
{"code": "const cmd = `
$ErrorActionPreference='Continue'
$root = 'C:\\Users\\Administrator\\.dsh\\sessions'
if (Test-Path $root) {
  Write-Output ('sessions dir exists; files=' + (Get-ChildItem $root -Recurse -File -ErrorAction SilentlyContinue | Measure-Object).Count)
  Get-ChildItem $root -Recurse -File -ErrorAction SilentlyContinue | Select-Object -First 15 FullName,Length
} else { Write-Output 'no sessions dir' }
`;
const r = await tools.pwsh({ description: "Inspect DSH sessions store", command: cmd, workdir: "D:\\lean", timeoutMs: 120000 });
console.log(r.kind==="foreground" ? r.stdout.text.slice(0,3000) : JSON.stringify(r));
", "description": "Inspect DSH sessions directory layout"}

